37		if err != nil {
38			t.Fatal(err)
39		}
40		if string(after) != string(before) {
41			t.Fatal("state file changed despite the failed save")
42		}
43		entries, err := os.ReadDir(dir)
44		if err != nil {
45			t.Fatal(err)
46		}
47		var names []string
48		for _, e := range entries {
49			names = append(names, e.Name())
50		}
