52			t.Fatalf("failed save must not leave temp files, dir contains %v", names)
53		}
54	}
55	
56	// assertOldTxQueued 断言旧交易在失败的替换后保持操作前形态：仍排队、完整内容
57	// 与原交易逐字段一致、费用与标识不变，替代交易关联为空，也不带确认块关联。
58	func assertOldTxQueued(t *testing.T, n *Node, old *Transaction) {
