61		if info.Status != StatusQueued {
62			t.Fatalf("old tx status = %s, want queued after the failed replacement", info.Status)
63		}
64		assertTxMatches(t, info.Tx, old)
65		if info.ReplacedBy != "" {
66			t.Fatalf("old tx replacement link = %q, want empty after the failed replacement", info.ReplacedBy)
67		}
