// 发送者公钥、内容、签名、费用、序号、到期轮次全部改写。
func tamperQueryTx(tx *Transaction) {
	tx.Sender[0] ^= 0xff
	tx.Content = append(tx.Content, "tampered"...)
	tx.Signature[0] ^= 0xff
	tx.Fee += 1000
	tx.Sequence += 100
	tx.Expiry = 1 // 改为当前轮次，试图让交易立即到期
}

